INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(122580, 'ruRU', '', 'Держи руки при себе, малыш.', 24330),
(122581, 'ruRU', '', 'Веди себя тихо и дай матери осмотреться.', 24330),
(122582, 'ruRU', '', 'Не трогай пальцами стекло, помни, о чём мы договорились.', 24330),
(122583, 'ruRU', '', 'Если ты это разобьёшь, матери придётся это купить.', 24330),
(122584, 'ruRU', '', 'Успокойся, мы скоро пойдём домой.', 24330),
(122591, 'ruRU', '', 'Некоронованные — средство для достижения цели. Конца Легиона.', 24330),
(122602, 'ruRU', '', 'Храм Тысячи Огней кишит обезумевшими духами. Тебе стоит напомнить им о приличиях.', 24330),
(122603, 'ruRU', '', 'Даже духи понимают силу. Отлично сделано!', 24330),
(122604, 'ruRU', '', 'Самые могущественные маги этого храма сговариваются против Ночных Стражей. Покажи им, как мы поступаем с нашими врагами!', 24330),
(122606, 'ruRU', '', 'Отлично сражался! Враги Ночных Стражей дорого заплатили за своё предательство.', 24330),
(122608, 'ruRU', '', 'Почему мы сражаемся?', 24330),
(122609, 'ruRU', '', 'Да''а! Теперь ты меня злишь!', 24330),
(122625, 'ruRU', '', 'Я знааааю, ты с Легииооном. Это ты. Вот как ты звучишь.', 24330),
(122626, 'ruRU', '', 'Ко мне, мой ящик, а ты проваливай!', 24330),
(122628, 'ruRU', '', 'Я говорил им, что так и будет.\n\nЯ ИМ ГОВОРИЛ.\n\nОни слушали?!', 24330),
(122634, 'ruRU', '', 'Враги из Кошмара хитрые. Они выбрали момент, когда Дикие Боги падали в бою тысячи лет назад, когда они восстали защищать Азерот от Пылающего Легиона.', 24330),
(122635, 'ruRU', '', 'Мне совсем не нравится это место! Давай избавимся от этих вторгшихся монстров, архидруид!', 24330),
(122636, 'ruRU', '', 'Диким богам, должно быть, тяжело заново переживать этот момент. Могу лишь представить ужас того вторжения Легиона, столько лет назад.', 24330),
(122639, 'ruRU', '', 'Ты пришёл к горну всего творения в поисках ответов. Так слушай же и обрети просветление.', 24330),
(122640, 'ruRU', '', 'В давно минувшие времена была сражена великая битва, что определила судьбу всех миров. В той последней битве всесильный Пантеон титанов пал от руки одного из своих: Саргераса.', 24330),
(122641, 'ruRU', '', 'После того падения не осталось никого, кто мог противостоять воле Саргераса. Свободный от оков, тёмный титан и его Пылающий Легион продолжили уничтожать бесчисленные миры в своём Пылающем Походе.', 24330),
(122642, 'ruRU', '', 'Из пепла тех разорённых миров поднялись выжившие, чтобы противостоять демонам. Они стали известны как Армия Света.', 24330),
(122643, 'ruRU', '', 'Но теперь Золотая Армия балансирует на краю забвения, пока их поход на Аргус близится к завершению. Если они падут, Легион начнёт новый Пылающий Поход, и с ним содрогнётся весь космос.', 24330),
(122644, 'ruRU', '', 'Я здесь сейчас с миссией отчаяния. Я ищу дитя Света и Тьмы: мальчика, которому суждено положить конец эпохе демонов.', 24330),
(122645, 'ruRU', '', 'Того, кого зовут Иллидан Ярость Бури.', 24330),
(122649, 'ruRU', '', '$n, это ты.\n\nМы преследовали опасного повелителя ужаса. К сожалению, он заманил нас прямо в ловушку.', 24330),
(122655, 'ruRU', '', 'Я Ксе''ра, один из первых наару, выкованных здесь во время великого упорядочивания космоса.', 24330),
(122656, 'ruRU', '', 'Не тревожься, смертный. Твоё сознание было спроецировано к моему астральному присутствию в Великом Тёмном Запределье.', 24330),
(122658, 'ruRU', '', 'XXXX', 24330),
(122659, 'ruRU', '', 'Удачи всем вам.', 24330),
(122681, 'ruRU', '', 'Не знаю, что нашло на эти цветы! Я перестал пытаться их собирать, когда они начали... ну, они начали собираться сами!$B$BСтранно, не правда ли?', 24330),
(122690, 'ruRU', '', 'Я изменил своё решение. Покажи мне снова, какие артефакты доступны.', 24330),
(122696, 'ruRU', '', 'Боль утихнет, защитник. Теперь ты несёшь мою метку, и через неё я могу видеть и чувствовать так же, как ты. Вернись ко мне, когда сможешь. У нас много дел.', 24330),
(122697, 'ruRU', '', 'Приветствую, $n. Как ты себя чувствуешь? Довольно многие другие сообщали о приступах тошноты и головокружения.', 24330),
(122698, 'ruRU', '', 'Приветствую! Ты только прибыл в город? Похоже, ты не страдаешь от побочных эффектов.', 24330),
(122700, 'ruRU', '', 'Мы не можем больше этого выносить!', 24330),
(122701, 'ruRU', '', 'Это бесконечно! Они просто продолжают прибывать!', 24330),
(122702, 'ruRU', '', 'Это не может продолжаться вечно! Нас скоро захлестнёт!', 24330),
(122703, 'ruRU', '', 'Им придётся скоро переместить город! Мы не можем продолжать так дальше!', 24330),
(122704, 'ruRU', '', 'У Совета есть план. Я уверен в этом!', 24330);
